import sys
from collections import defaultdict

INF = -10**15

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        if self.n == 0:
            self.size = 0
            self.tree = []
            self.lazy = []
            return
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = max(self.tree[2*i], self.tree[2*i+1])

    def apply(self, i, val):
        if i < len(self.tree):
            self.tree[i] += val
            if i < self.size:
                self.lazy[i] += val

    def push(self, i):
        if self.lazy[i] != 0:
            if i < self.size:
                self.tree[2*i] += self.lazy[i]
                self.tree[2*i+1] += self.lazy[i]
                self.lazy[2*i] += self.lazy[i]
                self.lazy[2*i+1] += self.lazy[i]
            self.lazy[i] = 0

    def update(self, l, r, delta, i=1, segL=0, segR=None):
        if segR is None:
            segR = self.size - 1
        if r < segL or l > segR:
            return
        if l <= segL and segR <= r:
            self.apply(i, delta)
            return
        self.push(i)
        mid = (segL + segR) // 2
        self.update(l, r, delta, 2*i, segL, mid)
        self.update(l, r, delta, 2*i+1, mid+1, segR)
        self.tree[i] = max(self.tree[2*i], self.tree[2*i+1])

    def query(self, l, r, i=1, segL=0, segR=None):
        if segR is None:
            segR = self.size - 1
        if r < segL or l > segR:
            return INF
        if l <= segL and segR <= r:
            return self.tree[i]
        self.push(i)
        mid = (segL + segR) // 2
        left_q = self.query(l, r, 2*i, segL, mid)
        right_q = self.query(l, r, 2*i+1, mid+1, segR)
        return max(left_q, right_q)

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    A = list(map(int, data[1:1+n]))

    left_dist = [0] * n
    freq_left = defaultdict(int)
    distinct = 0
    for i in range(n):
        freq_left[A[i]] += 1
        if freq_left[A[i]] == 1:
            distinct += 1
        left_dist[i] = distinct

    right_dist = [0] * n
    freq_right = defaultdict(int)
    distinct = 0
    for i in range(n-1, -1, -1):
        freq_right[A[i]] += 1
        if freq_right[A[i]] == 1:
            distinct += 1
        right_dist[i] = distinct

    prev_occ = [-1] * n
    freq_prev = defaultdict(int)
    for i in range(n):
        if freq_prev[A[i]] > 0:
            prev_occ[i] = freq_prev[A[i]]
        else:
            prev_occ[i] = -1
        freq_prev[A[i]] += 1
    pos = [p + 1 for p in prev_occ]

    n_val = n - 1
    arr = [left_dist[i] for i in range(n_val)]

    if n_val > 0:
        seg_tree = SegmentTree(arr)
    else:
        seg_tree = None

    ans = 0
    for j in range(1, n-1):
        L = max(1, pos[j])
        segL = L - 1
        segR = j - 1
        if segL <= segR and segR < n_val:
            seg_tree.update(segL, segR, 1)
        current_max = seg_tree.query(0, j-1)
        if current_max == INF:
            current_max = 0
        total = current_max + right_dist[j+1]
        if total > ans:
            ans = total

    print(ans)

