def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    A = list(map(int, data[1:1+n]))

    L = [0] * (n + 1)
    freq = [0] * (n + 1)
    current = 0
    for i in range(n):
        if freq[A[i]] == 0:
            current += 1
        freq[A[i]] += 1
        L[i + 1] = current

    R = [0] * (n + 1)
    freq = [0] * (n + 1)
    current = 0
    for i in range(n - 1, -1, -1):
        if freq[A[i]] == 0:
            current += 1
        freq[A[i]] += 1
        R[i] = current
    R[n] = 0

    if n < 3:
        print(0)
        return

    j = 1
    current_distinct = 0
    freq_mid = [0] * (n + 1)

    if n >= 2:
        if freq_mid[A[1]] == 0:
            current_distinct = 1
        freq_mid[A[1]] += 1

    max_total = 0
    for i in range(0, n - 2):
        while j < n - 1:
            next_distinct = current_distinct + (1 if freq_mid[A[j + 1]] == 0 else 0)
            next_sum = next_distinct + R[j + 2]
            current_sum = current_distinct + R[j + 1]
            if next_sum > current_sum:
                freq_mid[A[j + 1]] += 1
                j += 1
            else:
                break

        total = L[i + 1] + current_distinct + R[j + 1]
        if total > max_total:
            max_total = total

        if freq_mid[A[i + 1]] == 1:
            current_distinct -= 1
        freq_mid[A[i + 1]] -= 1

        if j == i + 1:
            j = i + 2
            current_distinct = 0
            if i + 2 < n:
                if freq_mid[A[i + 2]] == 0:
                    current_distinct = 1
                freq_mid[A[i + 2]] += 1

    print(max_total)

